<?php require __DIR__.'/config.php';$u=require_login();$b=require_business();if(!can('services')){http_response_code(403);exit('Forbidden');}$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action']??'';$map=['accepted'=>'accepted','in_progress'=>'in_progress','completed'=>'completed','cancelled'=>'cancelled'];if(isset($map[$action])){try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT * FROM service_requests WHERE id=? AND business_id=? FOR UPDATE");$s->execute([$id,$b['id']]);$r=$s->fetch();if(!$r)throw new RuntimeException('Request not found.');if($r['status']===$map[$action]){$pdo->commit();flash('Request is already '.strtolower($map[$action]).'.');redirect('requests.php');}$trans=['new'=>['accepted','cancelled'],'accepted'=>['in_progress','cancelled'],'in_progress'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]];if(!in_array($map[$action],$trans[$r['status']]??[],true))throw new RuntimeException('Invalid status transition.');$s=$pdo->prepare("UPDATE service_requests SET status=?,assigned_to=?,updated_at=NOW() WHERE id=? AND business_id=? AND status=?");$s->execute([$map[$action],$u['id'],$id,$b['id'],$r['status']]);if($s->rowCount()!==1)throw new RuntimeException('Request changed before this action was saved. Please refresh.');$h=$pdo->prepare("INSERT INTO service_request_history(request_id,business_id,user_id,from_status,to_status,created_at) VALUES(?,?,?,?,?,NOW())");$h->execute([$id,$b['id'],$u['id'],$r['status'],$map[$action]]);$pdo->commit();notify_business((int)$b['id'],'Service request update',$r['type'].' from '.($r['location_id']?'the guest location':'a guest').' · '.strtoupper($map[$action]),$u['id'],'requests.php','requests');flash('Request updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}}redirect('requests.php');}
$s=$pdo->prepare("SELECT r.*,l.name location_name,u.name assigned_name FROM service_requests r LEFT JOIN locations l ON l.id=r.location_id LEFT JOIN users u ON u.id=r.assigned_to WHERE r.business_id=? ORDER BY r.created_at DESC LIMIT 100");$s->execute([$b['id']]);$rs=$s->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow">Hotel operations</div><h1>Service requests</h1><p>Every guest request is assigned to a staff account.</p></div></div><div class="alert" id="alertControls"><b>Service alerts</b><div class="small muted">Tap once on this phone to enable notification sound and spoken alerts.</div><button class="btn gold" id="enableAlerts" type="button" style="margin-top:10px">Enable alerts & voice</button></div><div id="liveNotice"></div><?php foreach($rs as $r):?><article class="order-card"><div class="order-top"><div><b><?=e($r['type'])?></b><span class="badge"><?=e(strtoupper($r['status']))?></span><div class="small muted"><?=e($r['location_name']??'Guest')?> · <?=e($r['created_at'])?></div></div></div><p><?=e($r['message']??'')?></p><div class="small">Assigned: <b><?=e($r['assigned_name']??'Unassigned')?></b></div><div class="actions"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="accepted">Accept</button><button class="btn" name="action" value="in_progress">In progress</button><button class="btn gold" name="action" value="completed">Complete</button></form></div></article><?php endforeach;if(!$rs):?><div class="panel"><p class="muted">No service requests yet.</p></div><?php endif;?><script>(function(){let key='serv_request_last_notification';let last=Number(localStorage.getItem(key)||0);let enabled=localStorage.getItem('serv_alerts_enabled')==='1';function enable(){enabled=true;localStorage.setItem('serv_alerts_enabled','1');if(window.SERV)SERV.unlock();if('speechSynthesis'in window){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance('SERV alerts are enabled');u.rate=.9;speechSynthesis.speak(u)}catch(e){}}if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();const b=document.getElementById('enableAlerts');if(b)b.textContent='Alerts enabled ✓'}document.addEventListener('click',()=>window.SERV?.unlock(),{passive:true});document.getElementById('enableAlerts')?.addEventListener('click',enable);if(enabled){const b=document.getElementById('enableAlerts');if(b)b.textContent='Alerts enabled ✓'}async function poll(){try{const r=await fetch('api/notifications.php?after='+last,{cache:'no-store'});const d=await r.json();if(!d.ok)return;for(const n of d.notifications){last=Math.max(last,n.id);localStorage.setItem(key,String(last));if(enabled){window.SERV?.announce(n.title,n.body);if('Notification'in window&&Notification.permission==='granted'){try{const no=new Notification(n.title,{body:n.body,icon:'assets/icon.svg',tag:'serv-request-'+n.id});no.onclick=()=>location.href=n.url||'requests.php'}catch(e){}}}const box=document.getElementById('liveNotice');if(box)box.innerHTML='<div class="alert success"><b>'+n.title+'</b><div class="small">'+n.body+'</div></div>';if(n.url&&/requests\.php/.test(n.url))setTimeout(()=>location.reload(),800)}}catch(e){}}poll();setInterval(poll,3000)})();</script><?php include __DIR__.'/app/layout_bottom.php';
